var BaseConnector = class {
  /**
   * Executes the health check against the target endpoint
   */
  async execute(project, authSecret, context = {}) {
    const { url, method, headers } = this.prepareRequest(project, authSecret);
    const ssrfCheck = validateUrlForSSRF(url, context.allowHttp);
    if (!ssrfCheck.valid) {
      return {
        status: "failed",
        responseTimeMs: 0,
        error: `SSRF Blocked: ${ssrfCheck.error}`,
        message: `Endpoint destination failed SSRF safety checks.`
      };
    }
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), project.timeout_ms || 1e4);
    const startTime = Date.now();
    try {
      console.log(`[Connector Outbound] ${method} ${url}`, {
        headers,
        auth_type: project.auth_type,
        authSecretLength: authSecret?.length
      });
      const response = await fetch(url, {
        method,
        headers: {
          "User-Agent": context.userAgent || "HeartbeatManager/1.0",
          ...headers
        },
        signal: controller.signal,
        redirect: "manual"
        // Prevent SSRF redirect bypass
      });
      const responseTimeMs = Date.now() - startTime;
      clearTimeout(timeoutId);
      const isExpected = (project.expected_status_codes || [200, 204]).includes(response.status);
      const safeHeaders = {};
      const allowedHeaders = ["content-type", "server", "x-request-id", "cf-ray", "content-length"];
      for (const key of allowedHeaders) {
        const val = response.headers.get(key);
        if (val) safeHeaders[key] = val;
      }
      let responseBody = "";
      try {
        responseBody = await response.text();
      } catch (e) {
      }
      console.log(`[Connector Response] ${method} ${url} -> HTTP ${response.status} (${responseTimeMs}ms)`, {
        headers: safeHeaders,
        body: responseBody
      });
      if (isExpected) {
        return {
          status: "success",
          httpStatus: response.status,
          responseTimeMs,
          headers: safeHeaders,
          message: `Endpoint responded with expected HTTP ${response.status}`
        };
      } else if (response.status >= 500) {
        return {
          status: "failed",
          httpStatus: response.status,
          responseTimeMs,
          headers: safeHeaders,
          error: `HTTP ${response.status}: Server Error${responseBody ? ` - ${responseBody.slice(0, 200)}` : ""}`,
          message: `Endpoint returned server error ${response.status}`
        };
      } else {
        return {
          status: "warning",
          httpStatus: response.status,
          responseTimeMs,
          headers: safeHeaders,
          error: `HTTP ${response.status}: Unexpected status code (expected ${JSON.stringify(project.expected_status_codes)})${responseBody ? ` - ${responseBody.slice(0, 200)}` : ""}`,
          message: `Endpoint responded with unexpected HTTP ${response.status}`
        };
      }
    } catch (err) {
      clearTimeout(timeoutId);
      const responseTimeMs = Date.now() - startTime;
      if (err.name === "AbortError") {
        return {
          status: "failed",
          responseTimeMs,
          error: `Request timed out after ${project.timeout_ms || 1e4}ms`,
          message: "Connection timed out waiting for server response."
        };
      }
      return {
        status: "failed",
        responseTimeMs,
        error: err.message || "Unknown network error",
        message: `Network error: ${err.message || "Failed to connect"}`
      };
    }
  }
};

