    try {
      const result = await operation(attempt);
      if (!shouldRetry2(null, result) || attempt >= maxRetries) {
        return { result, attempts: attempt };
      }
    } catch (err) {
      if (!shouldRetry2(err) || attempt >= maxRetries) {
        return { error: err, attempts: attempt };
      }
    }
    attempt++;
